/* ============================================================
   IRON DAWN — interface styling
   ============================================================ */
:root {
  --ink: #070a0b;
  --ink-soft: #0d1214;
  --panel: rgba(10, 15, 17, .88);
  --panel-solid: #0c1113;
  --steel: #829093;
  --steel-bright: #c4ced0;
  --sand: #d8ad65;
  --sand-hot: #f0ca83;
  --sand-deep: #9a6f31;
  --red: #dc4533;
  --red-deep: #7a1d18;
  --green: #9fcf94;
  --blue: #7fb5c9;
  --line: rgba(207, 224, 225, .17);
  --line-hot: rgba(216, 173, 101, .42);
  --display: "Arial Black", "Helvetica Neue", Impact, sans-serif;
  --condensed: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", "Courier New", monospace;
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; }
html { background: var(--ink); }
body {
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: #eef1ec;
  font-family: var(--condensed);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}
button { font: inherit; color: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
button:focus-visible { outline: 2px solid var(--sand-hot); outline-offset: 4px; }
.is-hidden { display: none !important; }
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 21px;
  padding: 0 6px;
  border: 1px solid rgba(220, 235, 235, .3);
  border-bottom-color: rgba(255,255,255,.12);
  background: rgba(255,255,255,.07);
  color: #e8efec;
  font: 700 10px/1 var(--mono);
  letter-spacing: .04em;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  isolation: isolate;
  overflow: hidden;
}
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #080b0c;
}
body.is-playing #game { cursor: none; }

/* ============================ screen FX ============================ */
.screen-fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 25;
}
.fx-grain {
  position: absolute;
  inset: -30%;
  opacity: .055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: grainShift .22s steps(2) infinite;
}
.fx-vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at center, transparent 43%, rgba(2, 5, 6, .35) 78%, rgba(1, 4, 5, .8) 112%),
    linear-gradient(90deg, rgba(0,0,0,.16), transparent 12%, transparent 88%, rgba(0,0,0,.2));
}
.fx-scanlines {
  position: absolute;
  inset: 0;
  opacity: .11;
  background: repeating-linear-gradient(0deg, transparent 0 2px, rgba(0,0,0,.35) 3px 4px);
  mix-blend-mode: multiply;
}
.damage-flash {
  position: absolute;
  inset: 0;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 28%, rgba(192, 24, 15, .62) 100%),
    linear-gradient(0deg, rgba(177,20,12,.18), transparent 44%);
  transition: opacity .16s ease;
}
.damage-flash.active { opacity: 1; transition: none; }
@keyframes grainShift {
  0% { transform: translate3d(0,0,0); }
  25% { transform: translate3d(-3%, 2%, 0); }
  50% { transform: translate3d(2%, -3%, 0); }
  75% { transform: translate3d(3%, 3%, 0); }
  100% { transform: translate3d(-2%, -1%, 0); }
}

/* ============================ MENU ============================ */
.menu {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  grid-template-rows: auto 1fr auto;
  padding: clamp(18px, 3vw, 42px) clamp(22px, 4.7vw, 78px) clamp(18px, 3vh, 34px);
  background:
    linear-gradient(90deg, rgba(5,8,9,.96) 0%, rgba(5,8,9,.9) 34%, rgba(5,8,9,.4) 64%, rgba(5,8,9,.05) 100%),
    linear-gradient(0deg, rgba(5,8,9,.92), transparent 30%, transparent 72%, rgba(5,8,9,.6));
  overflow: hidden auto;
}
.menu::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(112deg, transparent 0 47.7%, rgba(216,173,101,.12) 47.8% 48%, transparent 48.1%),
    linear-gradient(112deg, transparent 0 59.7%, rgba(216,173,101,.07) 59.8% 59.9%, transparent 60%);
}
.menu::after {
  content: "";
  position: absolute;
  left: clamp(22px, 4.7vw, 78px);
  top: 0;
  width: 1px;
  height: 100%;
  background: linear-gradient(transparent, rgba(216,173,101,.36) 18%, rgba(216,173,101,.1) 70%, transparent);
  pointer-events: none;
}
.menu-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 72% 40%, rgba(225, 149, 58, .13), transparent 32%),
    radial-gradient(circle at 89% 80%, rgba(166, 53, 31, .11), transparent 32%);
  mix-blend-mode: screen;
}
.menu-topbar {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(216,173,101,.2);
  font: 700 10px/1 var(--mono);
  letter-spacing: .22em;
  color: rgba(232, 238, 233, .64);
}
.brand-lockup { display: flex; align-items: center; gap: 10px; }
.brand-star { color: var(--sand); font-size: 13px; text-shadow: 0 0 16px rgba(216,173,101,.7); }
.brand-slash { color: var(--sand); padding: 0 5px; }
.build-tag { display: flex; align-items: center; gap: 8px; }
.build-tag b { color: var(--sand-hot); font-weight: 700; }
.live-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: #a8dda4; box-shadow: 0 0 10px #8bd983;
  animation: livePulse 1.9s ease-in-out infinite;
}
@keyframes livePulse { 50% { opacity: .3; box-shadow: 0 0 2px #8bd983; } }

.menu-layout {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1.38fr) minmax(300px, .62fr);
  gap: clamp(30px, 7vw, 120px);
  align-items: center;
  width: min(1420px, 100%);
  margin: 0 auto;
  padding: clamp(24px, 5vh, 64px) 0;
}
.hero-panel { max-width: 760px; }
.eyebrow {
  display: flex; align-items: center; gap: 12px;
  margin-bottom: clamp(10px, 2vh, 22px);
  color: var(--sand);
  font: 700 10px/1.2 var(--mono);
  letter-spacing: .3em;
  text-transform: uppercase;
}
.eyebrow span { width: 32px; height: 1px; background: var(--sand); box-shadow: 0 0 10px rgba(216,173,101,.5); }

.logo {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  margin: 0 0 clamp(12px, 2.4vh, 28px);
  font-family: var(--display);
  font-weight: 900;
  text-transform: uppercase;
  line-height: .76;
  letter-spacing: -.065em;
  filter: drop-shadow(0 18px 35px rgba(0,0,0,.55));
}
.logo-iron {
  position: relative;
  z-index: 1;
  color: #e9e7df;
  font-size: clamp(78px, 12.8vw, 192px);
  text-shadow: 0 1px 0 #fff6dc, 0 5px 0 #46443d, 0 8px 0 #282721, 0 18px 34px rgba(0,0,0,.7);
}
.logo-dawn {
  position: relative;
  z-index: 0;
  margin-top: -.02em;
  margin-left: .56em;
  color: transparent;
  font-size: clamp(78px, 12.8vw, 192px);
  -webkit-text-stroke: 2px var(--sand);
  text-shadow: 0 0 24px rgba(216,173,101,.23), 0 0 70px rgba(216,173,101,.1);
}
.logo-dawn::after {
  content: "DAWN";
  position: absolute;
  inset: 0;
  color: var(--sand);
  -webkit-text-stroke: 0;
  clip-path: inset(0 0 64% 0);
  opacity: .38;
}
.logo-rule {
  width: min(480px, 72%);
  height: 3px;
  margin-top: 18px;
  background: linear-gradient(90deg, var(--red) 0 18%, rgba(238,240,232,.85) 18% 44%, rgba(45,76,112,.9) 44% 66%, transparent 66% 100%);
}
.tagline {
  margin: 0 0 16px;
  font-size: clamp(20px, 2.6vw, 32px);
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: .015em;
  text-transform: uppercase;
  color: #dce1dc;
}
.tagline em { color: var(--sand-hot); font-style: normal; }
.brief {
  max-width: 580px;
  margin: 0 0 clamp(22px, 3.4vh, 36px);
  color: rgba(212, 222, 217, .63);
  font-size: clamp(12px, 1.18vw, 15px);
  line-height: 1.68;
  letter-spacing: .025em;
}
.brief b { color: #e8ece5; }
.hero-actions { display: flex; align-items: stretch; gap: 24px; }
.play-btn {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: 18px;
  min-width: clamp(230px, 24vw, 320px);
  padding: 15px 22px 15px 18px;
  border: 1px solid rgba(245, 213, 155, .7);
  background:
    linear-gradient(110deg, rgba(255,255,255,.1), transparent 42%),
    linear-gradient(180deg, #e6b76d, #b07a34 62%, #8d5d26);
  color: #16110a;
  text-align: left;
  cursor: pointer;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  box-shadow: 0 14px 38px rgba(129, 79, 23, .25), inset 0 1px 0 rgba(255,255,255,.48);
  transition: transform .16s ease, filter .16s ease;
  overflow: hidden;
}
.play-btn:hover { transform: translateY(-2px); filter: brightness(1.09); }
.play-btn:active { transform: translateY(1px) scale(.995); }
.play-icon {
  display: grid; place-items: center;
  width: 46px; height: 46px;
  border: 1px solid rgba(20,15,8,.34);
  background: rgba(18, 13, 7, .14);
  font-size: 15px;
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
}
.play-copy { display: flex; flex-direction: column; gap: 4px; }
.play-copy b { font-family: var(--display); font-size: 25px; line-height: .9; letter-spacing: .015em; }
.play-copy small { font: 700 8px/1 var(--mono); letter-spacing: .18em; opacity: .65; }
.play-sweep {
  position: absolute; inset: -40% auto -40% -30%;
  width: 22%;
  transform: skewX(-20deg) translateX(-200%);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.45), transparent);
  animation: playSweep 4.4s ease-in-out infinite 1.2s;
  pointer-events: none;
}
@keyframes playSweep { 0%, 58% { transform: skewX(-20deg) translateX(-200%); } 74%, 100% { transform: skewX(-20deg) translateX(750%); } }
.best-score {
  display: flex; flex-direction: column; justify-content: center; gap: 7px;
  padding-left: 22px;
  border-left: 1px solid rgba(216,173,101,.28);
}
.best-score span { color: rgba(218,228,223,.44); font: 700 8px/1 var(--mono); letter-spacing: .2em; }
.best-score strong { color: #e8d3aa; font: 700 20px/1 var(--mono); letter-spacing: .06em; }
.feature-chips { display: flex; flex-wrap: wrap; gap: 10px; margin-top: clamp(22px, 3.5vh, 38px); }
.feature-chips span {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(208,224,222,.16);
  background: rgba(7,12,13,.42);
  color: rgba(210,221,216,.6);
  font: 700 8px/1 var(--mono);
  letter-spacing: .16em;
}
.feature-chips b { color: var(--sand-hot); font-size: 12px; }

/* dossier */
.dossier {
  position: relative;
  justify-self: end;
  width: min(370px, 100%);
  padding: clamp(20px, 2vw, 28px);
  border: 1px solid rgba(206, 224, 221, .19);
  background:
    linear-gradient(135deg, rgba(255,255,255,.045), transparent 38%),
    linear-gradient(180deg, rgba(10,16,17,.78), rgba(7,11,12,.93));
  box-shadow: 0 28px 80px rgba(0,0,0,.4), inset 0 0 40px rgba(255,255,255,.01);
  backdrop-filter: blur(9px);
  transform: rotate(.35deg);
  clip-path: polygon(0 0, calc(100% - 24px) 0, 100% 24px, 100% 100%, 24px 100%, 0 calc(100% - 24px));
}
.dossier::after {
  content: "";
  position: absolute;
  right: 12px; top: 12px;
  width: 82px; height: 82px;
  border-top: 1px solid rgba(216,173,101,.14);
  border-right: 1px solid rgba(216,173,101,.14);
  pointer-events: none;
}
.dossier-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.dossier-kicker { color: var(--sand); font: 700 8px/1 var(--mono); letter-spacing: .22em; }
.stamp {
  padding: 4px 7px;
  color: #e37a6a;
  border: 1px solid rgba(220,69,51,.5);
  font: 700 7px/1 var(--mono);
  letter-spacing: .14em;
  transform: rotate(2deg);
}
.dossier-title {
  margin: 18px 0 20px;
  color: rgba(232,239,233,.44);
  font: 700 10px/1.1 var(--mono);
  letter-spacing: .17em;
}
.dossier-title b { color: #e7eae4; font: 900 27px/.95 var(--display); letter-spacing: -.02em; }
.dossier-map {
  position: relative;
  height: 142px;
  margin-bottom: 20px;
  border: 1px solid rgba(216,173,101,.2);
  background:
    radial-gradient(circle at 50% 60%, rgba(216,173,101,.08), transparent 52%),
    #0a1011;
  overflow: hidden;
}
.map-grid {
  position: absolute; inset: 0;
  opacity: .34;
  background-image:
    linear-gradient(rgba(200,218,215,.13) 1px, transparent 1px),
    linear-gradient(90deg, rgba(200,218,215,.13) 1px, transparent 1px);
  background-size: 26px 26px;
  mask-image: linear-gradient(90deg, transparent, #000 16%, #000 84%, transparent);
}
.map-route {
  position: absolute;
  left: 34px; right: 34px; top: 68px;
  height: 1px;
  background: linear-gradient(90deg, rgba(216,173,101,.2), var(--sand) 16%, var(--sand) 84%, rgba(216,173,101,.2));
  box-shadow: 0 0 12px rgba(216,173,101,.2);
}
.map-node {
  position: absolute;
  display: grid; place-items: center;
  width: 18px; height: 18px;
  border: 1px solid var(--sand);
  background: #101515;
  color: #e9d8b4;
  font: 700 7px/1 var(--mono);
  transform: translate(-50%, -50%) rotate(45deg);
  box-shadow: 0 0 14px rgba(216,173,101,.14);
}
.map-node::after { content: ""; }
.map-node.n1 { left: 15%; top: 48%; }
.map-node.n2 { left: 32%; top: 48%; }
.map-node.n3 { left: 49%; top: 48%; }
.map-node.n4 { left: 66%; top: 48%; }
.map-node.n5 { left: 83%; top: 48%; border-color: #d9644f; color: #f0a99c; }
.map-label {
  position: absolute;
  color: rgba(219,229,223,.46);
  font: 700 6px/1 var(--mono);
  letter-spacing: .12em;
}
.map-label.l1 { left: 15%; top: 64%; transform: translateX(-50%); }
.map-label.l5 { left: 83%; top: 64%; transform: translateX(-50%); color: #d98d7d; }
.loadout { display: flex; flex-direction: column; }
.loadout-row {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 8px;
  padding: 10px 0;
  border-top: 1px solid rgba(207,224,221,.09);
}
.loadout-key { color: rgba(216,173,101,.75); font: 700 7px/1 var(--mono); letter-spacing: .12em; }
.loadout-name { color: #dfe5df; font-size: 11px; font-weight: 700; letter-spacing: .05em; }
.loadout-name small { color: rgba(220,230,224,.36); font: 700 7px/1 var(--mono); letter-spacing: .1em; }
.loadout-tag { color: rgba(220,230,224,.36); font: 700 7px/1 var(--mono); letter-spacing: .1em; }
.dossier-note {
  margin-top: 14px;
  padding: 12px 0 0 12px;
  border-top: 1px solid rgba(207,224,221,.09);
  border-left: 2px solid rgba(220,69,51,.5);
  color: rgba(212,222,217,.45);
  font: 10px/1.55 var(--mono);
  letter-spacing: .015em;
}
.menu-footer {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 22px;
  padding-top: 14px;
  border-top: 1px solid rgba(216,173,101,.18);
}
.controls-strip { display: flex; flex-wrap: wrap; align-items: center; gap: 7px 16px; }
.controls-label { color: var(--sand); font: 700 8px/1 var(--mono); letter-spacing: .18em; }
.controls-strip > span:not(.controls-label) {
  display: flex; align-items: center; gap: 5px;
  color: rgba(205,219,213,.49);
  font: 700 7px/1 var(--mono);
  letter-spacing: .09em;
}
.controls-strip kbd { height: 18px; min-width: 18px; font-size: 8px; padding: 0 4px; }
.footer-note { color: rgba(205,219,213,.3); font: 700 7px/1.4 var(--mono); letter-spacing: .13em; text-align: right; white-space: nowrap; }
.footer-note span { color: var(--sand); padding: 0 6px; }

/* ============================ HUD ============================ */
.hud {
  position: absolute;
  inset: 0;
  z-index: 12;
  pointer-events: none;
  color: #e9eeea;
  font-family: var(--condensed);
}
.hud button { pointer-events: auto; }
.hud-top {
  position: absolute;
  left: clamp(16px, 3vw, 44px);
  right: clamp(16px, 3vw, 44px);
  top: clamp(14px, 2.4vh, 26px);
  display: grid;
  grid-template-columns: minmax(250px, 340px) minmax(280px, 470px) minmax(230px, 310px);
  justify-content: space-between;
  gap: 18px;
  align-items: start;
}
.operator-card {
  display: flex;
  gap: 11px;
  padding: 9px 13px 10px 9px;
  border: 1px solid rgba(216,173,101,.23);
  border-left: 2px solid rgba(216,173,101,.65);
  background: linear-gradient(90deg, rgba(8,12,13,.9), rgba(8,12,13,.52));
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  backdrop-filter: blur(7px);
}
.portrait {
  position: relative;
  flex: 0 0 54px;
  height: 58px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  border: 1px solid rgba(216,173,101,.34);
  background:
    radial-gradient(circle at 50% 32%, rgba(216,173,101,.27), transparent 44%),
    repeating-linear-gradient(135deg, rgba(255,255,255,.03) 0 1px, transparent 1px 5px),
    #0e1516;
  overflow: hidden;
}
.portrait::before {
  content: "";
  position: absolute; left: 50%; bottom: 5px;
  width: 33px; height: 33px;
  border-radius: 50% 50% 45% 45%;
  background: linear-gradient(180deg, #b89c74, #6e5c42);
  transform: translateX(-50%);
  box-shadow: 0 -11px 0 -3px #2d3c35, 0 -14px 0 -1px #202c27;
}
.portrait::after {
  content: "";
  position: absolute; left: 50%; bottom: -13px;
  width: 50px; height: 31px;
  border-radius: 48% 48% 0 0;
  background: linear-gradient(90deg, #273c34, #3a5144 48%, #1f302a);
  transform: translateX(-50%);
}
.portrait-rank {
  position: absolute; left: 4px; top: 4px;
  color: #d7ba86; font: 700 6px/1 var(--mono); letter-spacing: .08em; z-index: 2;
}
.portrait-star {
  position: absolute; right: 4px; top: 3px;
  color: #e2c38b; font-size: 7px; z-index: 2;
  text-shadow: 0 0 8px rgba(216,173,101,.7);
}
.operator-info { flex: 1; min-width: 0; padding-top: 2px; }
.operator-name { margin-bottom: 7px; color: #e8ece5; font: 700 9px/1 var(--mono); letter-spacing: .1em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.operator-name span { color: var(--sand); font-size: 8px; }
.health-row { display: flex; align-items: center; gap: 9px; }
.health-bar {
  position: relative;
  flex: 1;
  height: 11px;
  border: 1px solid rgba(222,234,230,.18);
  background: rgba(218,231,225,.1);
  overflow: hidden;
}
.health-fill {
  position: absolute; inset: 0 auto 0 0;
  width: 100%;
  background: linear-gradient(90deg, #b7402e, #e06b43 58%, #e5a05f);
  box-shadow: 0 0 14px rgba(224,93,55,.34);
  transition: width .16s ease;
}
.armor-fill {
  position: absolute; left: 0; bottom: 0;
  height: 3px; width: 0;
  background: linear-gradient(90deg, #4e8da7, #8ac3d4);
  box-shadow: 0 0 9px rgba(112,183,205,.5);
  transition: width .2s ease;
}
.health-text { width: 27px; color: #f2dfbf; font: 700 15px/1 var(--mono); text-align: right; text-shadow: 0 1px 4px #000; }
.status-row { display: flex; gap: 7px; margin-top: 6px; color: rgba(205,222,216,.35); font: 700 6px/1 var(--mono); letter-spacing: .13em; }
.status-sep { color: rgba(216,173,101,.5); }
#stanceText { color: rgba(159,207,148,.65); }

.mission-card {
  padding: 9px 15px 11px;
  border-top: 1px solid rgba(216,173,101,.36);
  background: linear-gradient(90deg, transparent, rgba(8,12,13,.72) 14%, rgba(8,12,13,.72) 86%, transparent);
  text-align: center;
}
.mission-line { display: flex; justify-content: center; align-items: center; gap: 8px; color: rgba(224,234,228,.62); font: 700 8px/1 var(--mono); letter-spacing: .16em; }
.mission-line span:first-child { color: var(--sand); }
.mission-divider { color: rgba(216,173,101,.3); }
#missionName { color: #dde5df; }
.objective-line { display: flex; justify-content: center; align-items: center; gap: 9px; margin-top: 8px; color: #f0e3c8; font: 700 10px/1.15 var(--mono); letter-spacing: .1em; text-shadow: 0 1px 6px #000; }
.objective-diamond { width: 7px; height: 7px; border: 1px solid var(--sand); transform: rotate(45deg); box-shadow: 0 0 9px rgba(216,173,101,.6); }
.mission-progress { color: rgba(216,173,101,.74); font-size: 8px; }
.objective-track {
  position: relative;
  height: 2px;
  margin: 9px auto 0;
  width: min(300px, 92%);
  background: rgba(216,173,101,.14);
  overflow: visible;
}
.objective-fill { height: 100%; width: 0%; background: linear-gradient(90deg, rgba(216,173,101,.35), var(--sand)); box-shadow: 0 0 7px rgba(216,173,101,.4); transition: width .25s ease; }
.objective-marker {
  position: absolute; left: 0%; top: 50%;
  width: 5px; height: 5px;
  margin: -2px 0 0 -2px;
  background: #f4dcb2;
  transform: rotate(45deg);
  box-shadow: 0 0 8px var(--sand);
  transition: left .25s ease;
}

.hud-stats { display: flex; justify-content: flex-end; align-items: flex-start; gap: 15px; }
.score-block, .kills-block { display: flex; flex-direction: column; gap: 4px; text-align: right; }
.score-block span, .kills-block span { color: rgba(211,224,218,.42); font: 700 7px/1 var(--mono); letter-spacing: .17em; }
.score-block strong { color: #e8d8b6; font: 700 17px/1 var(--mono); letter-spacing: .04em; text-shadow: 0 1px 7px #000; }
.kills-block strong { color: #e7ece6; font: 700 17px/1 var(--mono); text-shadow: 0 1px 7px #000; }
.hud-buttons { display: flex; gap: 5px; }
.icon-btn {
  display: grid; place-items: center;
  width: 28px; height: 28px;
  border: 1px solid rgba(218,232,226,.23);
  background: rgba(8,12,13,.55);
  color: rgba(230,238,232,.7);
  font: 700 10px/1 var(--mono);
  cursor: pointer;
  transition: border-color .15s, background .15s, color .15s;
}
.icon-btn:hover { color: #f0e0bf; border-color: rgba(216,173,101,.6); background: rgba(216,173,101,.13); }

.kill-feed {
  position: absolute; top: clamp(92px, 15vh, 148px); right: clamp(16px, 3vw, 44px);
  display: flex; flex-direction: column; align-items: flex-end; gap: 6px;
  width: 260px;
}
.feed-item {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 9px;
  border-right: 2px solid rgba(220,69,51,.75);
  background: linear-gradient(90deg, transparent, rgba(7,10,11,.78));
  color: rgba(225,235,229,.75);
  font: 700 8px/1 var(--mono);
  letter-spacing: .1em;
  animation: feedIn .22s ease both;
}
.feed-item b { color: #efc98b; }
.feed-item .feed-score { color: #d46c56; }
@keyframes feedIn { from { opacity: 0; transform: translateX(16px); } }
.feed-item.out { animation: feedOut .35s ease forwards; }
@keyframes feedOut { to { opacity: 0; transform: translateX(24px); } }

.combo-badge {
  position: absolute; right: clamp(20px, 3.4vw, 52px); top: clamp(152px, 23vh, 216px);
  display: flex; align-items: baseline; gap: 8px;
  padding: 6px 10px;
  border: 1px solid rgba(216,173,101,.32);
  background: rgba(8,12,13,.48);
  color: rgba(229,238,232,.55); font: 700 7px/1 var(--mono); letter-spacing: .15em;
}
.combo-badge b { color: var(--sand-hot); font: 900 17px/1 var(--display); letter-spacing: 0; }
.toast {
  position: absolute; left: 50%; top: 22%;
  transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 9px 24px;
  border-top: 1px solid rgba(216,173,101,.5);
  border-bottom: 1px solid rgba(216,173,101,.28);
  background: linear-gradient(90deg, transparent, rgba(8,12,13,.8) 20%, rgba(8,12,13,.8) 80%, transparent);
  animation: toastIn .25s ease both;
  text-align: center;
}
.toast span { color: var(--sand); font: 700 7px/1 var(--mono); letter-spacing: .2em; }
.toast b { color: #f2ead9; font: 700 12px/1.1 var(--mono); letter-spacing: .1em; }
.toast.out { animation: toastOut .35s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -8px); } }
@keyframes toastOut { to { opacity: 0; transform: translate(-50%, -10px); } }
.prompt {
  position: absolute; left: 50%; bottom: 20%;
  transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px;
  padding: 7px 12px;
  border: 1px solid rgba(216,173,101,.35);
  background: rgba(7,11,12,.8);
  color: #e9e0cd; font: 700 8px/1 var(--mono); letter-spacing: .13em;
  animation: promptPulse 1.5s ease-in-out infinite;
}
.prompt kbd { border-color: var(--sand); color: var(--sand-hot); }
@keyframes promptPulse { 50% { border-color: rgba(216,173,101,.72); box-shadow: 0 0 18px rgba(216,173,101,.16); } }

.boss-wrap {
  position: absolute; left: 50%; bottom: clamp(124px, 18vh, 170px);
  width: min(540px, 72vw);
  transform: translateX(-50%);
  text-align: center;
}
.boss-head { display: flex; justify-content: space-between; align-items: baseline; gap: 14px; margin-bottom: 7px; }
.boss-head span { color: #efdab5; font: 700 11px/1 var(--mono); letter-spacing: .15em; }
.boss-head b { color: #d46754; font: 700 7px/1 var(--mono); letter-spacing: .18em; }
.boss-track { position: relative; height: 6px; border: 1px solid rgba(220,69,51,.42); background: rgba(36,7,5,.6); overflow: hidden; }
.boss-fill { width: 100%; height: 100%; background: linear-gradient(90deg, #7e2119, #db4e37 68%, #efa46b); box-shadow: 0 0 14px rgba(220,69,51,.5); transition: width .18s; }
.boss-sub { margin-top: 6px; color: rgba(231,180,160,.55); font: 700 7px/1 var(--mono); letter-spacing: .25em; }

.hud-bottom {
  position: absolute; left: clamp(16px, 3vw, 44px); right: clamp(16px, 3vw, 44px); bottom: clamp(16px, 3vh, 30px);
  display: flex; justify-content: space-between; align-items: flex-end; gap: 20px;
}
.field-tips { display: flex; flex-direction: column; gap: 6px; max-width: 290px; padding-bottom: 3px; }
.tip-label { color: var(--sand); font: 700 7px/1 var(--mono); letter-spacing: .22em; }
#fieldTip { color: rgba(212,225,219,.44); font: 10px/1.45 var(--mono); letter-spacing: .01em; }
.weapon-card {
  position: relative;
  width: min(348px, 38vw);
  padding: 10px 13px 9px;
  border: 1px solid rgba(216,173,101,.3);
  background:
    linear-gradient(115deg, rgba(216,173,101,.08), transparent 45%),
    linear-gradient(180deg, rgba(9,14,15,.88), rgba(7,11,12,.63));
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
  backdrop-filter: blur(8px);
}
