  finishReload() {
    const p = this.player;
    if (!p) return;
    const cfg = WEAPONS[p.weaponId];
    const ammo = p.ammo[p.weaponId];
    if (!cfg || !ammo) return;
    const need = cfg.magSize - ammo.mag;
    const take = Math.min(need, ammo.reserve);
    ammo.mag += take;
    ammo.reserve -= take;
    p.reloading = false;
    p.reloadTimer = 0;
    p.reloadProgress = 0;
    this.audio.reloadDone();
    this.weaponDirty = true;
