updateDying(dt) {
  this.deathTimer -= dt;
  this.updateParticles(dt * 0.45);
  this.updateEffects(dt * 0.45);
  this.updateTexts(dt * 0.45);
  this.updateCamera(dt * 0.3);
  this.flash = Math.max(0, this.flash - dt * 1.2);
  if (this.deathTimer <= 0) this.showGameOver();
}

