}
.brand-lockup { display: flex; align-items: center; gap: 10px; }
.brand-star { color: var(--sand); font-size: 13px; text-shadow: 0 0 16px rgba(216,173,101,.7); }
.brand-slash { color: var(--sand); padding: 0 5px; }
.build-tag { display: flex; align-items: center; gap: 8px; }
.build-tag b { color: var(--sand-hot); font-weight: 700; }
.live-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: #a8dda4; box-shadow: 0 0 10px #8bd983;
  animation: livePulse 1.9s ease-in-out infinite;
}
@keyframes livePulse { 50% { opacity: .3; box-shadow: 0 0 2px #8bd983; } }

.menu-layout {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1.38fr) minmax(300px, .62fr);
  gap: clamp(30px, 7vw, 120px);
  align-items: center;
  width: min(1420px, 100%);
  margin: 0 auto;
  padding: clamp(24px, 5vh, 64px) 0;
}
.hero-panel { max-width: 760px; }
.eyebrow {
  display: flex; align-items: center; gap: 12px;
  margin-bottom: clamp(10px, 2vh, 22px);
