.ammo-block { display: flex; align-items: baseline; gap: 3px; color: #f3dfb9; font-family: var(--mono); }
#ammoMag { font-size: 27px; font-weight: 700; line-height: .8; letter-spacing: -.05em; }
.ammo-sep { color: rgba(216,173,101,.35); font-size: 15px; }
