.grenade-count { display: flex; align-items: center; gap: 5px; color: rgba(210,224,217,.44); font: 700 6px/1 var(--mono); letter-spacing: .12em; }
.grenade-count b { color: #d6e4d3; font: 700 12px/1 var(--mono); }
.grenade-icon { width: 7px; height: 10px; border-radius: 2px; background: #8ea487; box-shadow: inset 0 1px 0 #c1d4b8; }
.reload-track { position: absolute; left: 13px; right: 13px; bottom: 4px; height: 2px; background: rgba(216,173,101,.15); }
.reload-track > div { width: 0%; height: 100%; background: var(--sand-hot); box-shadow: 0 0 8px var(--sand); }
.low-health {
  position: absolute; inset: auto 0 100px 0;
  display: flex; justify-content: center;
  color: rgba(238,107,87,.7);
  font: 700 8px/1 var(--mono);
  letter-spacing: .4em;
  opacity: 0;
  transition: opacity .3s;
  text-shadow: 0 0 12px rgba(220,69,51,.7);
}
.low-health.active { opacity: 1; animation: lowPulse 1s ease-in-out infinite; }
@keyframes lowPulse { 50% { opacity: .3; } }

