loop(timestamp) {
  if (!this.lastFrame) this.lastFrame = timestamp;
  const frame = Math.min(0.05, (timestamp - this.lastFrame) / 1000);
  this.lastFrame = timestamp;
  this.acc += frame;
  let steps = 0;
  while (this.acc >= FIXED && steps < 5) {
    this.tick(FIXED);
    this.acc -= FIXED;
    steps++;
